import {mountShell} from '../shared/shell.js?v=0.9.0';import {escapeHtml as esc,readStore,writeStore,downloadText} from '../shared/utils.js?v=0.9.0';import {attachCardDrag} from '../shared/drag.js?v=0.9.0';import {LANES,create,request,move,preview,advance,runPolicy,configure,active} from './engine.js?v=0.9.0';
mountShell({active:'exceptions'});const KEY='thinking-lab:exceptions:v1',app=document.querySelector('#app');const f=n=>Number(n).toFixed(1),copy=v=>structuredClone(v);let s=create(),undo=[],comparisons=[],message='',dragOff=()=>{},storageOK=true;
try{const d=readStore(KEY,null);if(d?.s&&Number.isInteger(d.s.quarter)&&d.s.quarter>=0&&d.s.quarter<=6){preview(d.s);s=d.s;comparisons=d.comparisons||[];}}catch{}
const say=text=>document.querySelector('#status').textContent=text;function save(){storageOK=writeStore(KEY,{s,comparisons});}function change(next,text){undo.push(copy(s));undo=undo.slice(-35);s=next;message=text;save();render();say(text);}function attempt(fn){try{fn();}catch(e){message=e.message;render();say(message);}}
function card(e){const r=request(e.id),expired=s.quarter>=r.arrive+r.life;return `<article class="card ${e.plan==='retired'?'retired':''}" data-drag-id="${e.id}"><button class="card-handle" data-drag-handle aria-label="Drag ${esc(r.name)}" ${e.status==='retired'||s.quarter===6?'disabled':''}>${esc(r.name)}</button><p><strong>${expired?'Benefit ended':`+${r.value} / quarter`}</strong> <span class="meta">${!expired?`through Q${Math.min(6,r.arrive+r.life)}`:''}</span></p><p class="meta">${r.touches.join(' + ')} · first acceptance +${r.bonus}</p><p>Setup ${r.setup} · upkeep ${r.maint}/q</p><p class="meta">Standardise ${r.standard} · retire ${r.retire}</p><label class="sr-only" for="move-${e.id}">Move ${esc(r.name)}</label><select id="move-${e.id}" data-move="${e.id}" ${e.status==='retired'||s.quarter===6?'disabled':''}>${Object.entries(LANES).map(([k,v])=>`<option value="${k}" ${e.plan===k?'selected':''} ${k==='pending'&&e.status!=='pending'||k==='tailored'&&e.status==='standard'?'disabled':''}>${v}</option>`).join('')}</select></article>`;}
function render(){dragOff();const done=s.quarter===6,p=done?s.history.at(-1):preview(s);app.innerHTML=`<div class="bar"><div><strong>${done?'Six quarters complete':`Quarter ${s.quarter+1} of 6`}</strong> <span class="meta">Fictional value points · future requests arrive one quarter at a time</span></div><div class="bar-group"><button class="button" id="undo" ${!undo.length?'disabled':''}>Undo</button><button class="button" id="reset">${done?'Replay this sequence':'Reset run'}</button>${!done?'<button class="button primary" id="advance">Settle quarter & reveal next</button>':''}</div></div><div class="stats"><div class="stat"><span>${done?'Final accumulated value':'Accumulated value'}</span><strong>${f(s.value)}</strong><small>${s.quarter} quarters settled</small></div><div class="stat"><span>${done?'Last quarter revenue':'This quarter’s revenue'}</span><strong class="good">+${f(p.revenue)}</strong><small>Recurring benefit + first-acceptance benefit</small></div><div class="stat"><span>Change + operating costs</span><strong>${f(p.changeCost+p.maintenance+p.retirement)}</strong><small>${f(p.changeCost)} setup · ${f(p.maintenance)} upkeep · ${f(p.retirement)} exit</small></div><div class="stat"><span>${done?'Last quarter net':'If you settle this plan'}</span><strong class="${p.net>=0?'good':'bad'}">${p.net>=0?'+':''}${f(p.net)}</strong><small>${f(p.reuse)} setup points saved through reuse</small></div></div>${message?`<p class="notice">${esc(message)}</p>`:''}<div class="board">${Object.entries(LANES).map(([lane,label])=>`<section class="lane" data-drop-id="${lane}"><h2>${label} <span class="meta">${s.entries.filter(e=>e.plan===lane).length}</span></h2><p class="lane-caption">${{pending:'Unchosen requests expire when this quarter settles.',tailored:'Quick setup, recurring upkeep and possible interactions.',standard:'Pay to generalise. Lower upkeep; reusable setup for related work.',retired:'Exit cost for live work; no future benefit or upkeep.'}[lane]}</p><div class="lane-items">${s.entries.filter(e=>e.plan===lane).map(card).join('')||'<p class="empty">Drop a request here, or use its move menu.</p>'}</div></section>`).join('')}</div><div class="two-columns"><section class="panel"><h2>Where the extra work comes from</h2>${p.pairs.length?p.pairs.map(pair=>`<div class="list-row"><span>${esc(request(pair.a).name)} × ${esc(request(pair.b).name)}<br><span class="meta">Shared surface: ${pair.overlap.join(', ')}</span></span><strong>${f(pair.cost)} / q</strong></div>`).join(''):'<p class="hint">No accepted implementations currently share a surface. An isolated exception can remain a good bargain.</p>'}<p class="hint">Standards reduce pair friction to one third and save up to 6 setup points on new related tailored work. Upkeep continues after benefit expires until you retire the work.</p></section><section class="panel"><h2>${done?'Compare rules on this same sequence':'Challenge the cost assumptions'}</h2>${done?`<p class="hint">Both rules see only the requests revealed each quarter and retire work when its benefit ends.</p><div class="bar-group"><button class="button" data-policy="tailor">Keep all requests tailored</button><button class="button" data-policy="reuse">Standardise when ≥3 quarters remain</button></div>${comparisons.length?`<div class="table-wrap"><table><thead><tr><th>Rule</th><th>Total value</th></tr></thead><tbody><tr><td>Your run</td><td>${f(s.value)}</td></tr>${comparisons.map(c=>`<tr><td>${esc(c.name)}</td><td>${f(c.value)}</td></tr>`).join('')}</tbody></table></div>`:''}`:`<div class="field"><label for="aging">Extra upkeep per quarter of age <output>${f(s.aging)}</output></label><input id="aging" type="range" min="0" max="3" step="0.1" value="${s.aging}" ${s.quarter?'disabled':''}></div><div class="field"><label for="pairCost">Friction per overlapping pair <output>${f(s.pairCost)}</output></label><input id="pairCost" type="range" min="0" max="6" step="0.5" value="${s.pairCost}" ${s.quarter?'disabled':''}></div><p class="hint">Set these before the first settlement so comparisons keep the same rules. Low interaction costs favour accommodation; high costs can justify generalisation.</p>`}</section></div>${s.history.length?`<section class="panel"><h2>The quarters you have settled</h2><div class="table-wrap"><table><thead><tr><th>Quarter</th><th>Revenue</th><th>Setup</th><th>Upkeep + interactions</th><th>Retire</th><th>Net</th></tr></thead><tbody>${s.history.map(h=>`<tr><td>Q${h.quarter+1}</td><td>${f(h.revenue)}</td><td>${f(h.changeCost)}</td><td>${f(h.maintenance)}</td><td>${f(h.retirement)}</td><td>${f(h.net)}</td></tr>`).join('')}</tbody></table></div></section>`:''}<div class="footer-row"><details><summary>Mechanism and limits</summary><p>Revenue is recurring value while the request is live, plus a first-acceptance bonus. Net value subtracts setup/generalisation, base upkeep, ageing, pair friction and explicit retirement costs. Standard upkeep is 40% of base; standards do not age. A pair is charged once if its surface tags overlap.</p><p>This is a fictional product-maintenance model, not a prediction of customer value. No engineering capacity limit, opportunity queue, discounting or hidden probabilistic failures. Retirement is final after settlement; Undo and replay can revisit it. A replay is informed by requests you have already seen.</p></details><button class="button" id="export">Export run</button></div><p class="save-note">${storageOK?'This run is saved in this browser.':'Storage is unavailable; export to keep this run.'}</p>`;bind();dragOff=attachCardDrag({root:app,onDrop:({itemId,dropId})=>attempt(()=>change(move(s,itemId,dropId),'Plan updated; costs settle only when you advance.'))});}
function bind(){app.querySelectorAll('[data-move]').forEach(el=>el.addEventListener('change',()=>attempt(()=>change(move(s,el.dataset.move,el.value),'Plan updated.'))));app.querySelector('#advance')?.addEventListener('click',()=>change(advance(s),'Quarter settled. New requests, if any, are now visible.'));app.querySelector('#undo').onclick=()=>{if(undo.length){s=undo.pop();message='Last change undone.';save();render();}};app.querySelector('#reset').onclick=()=>{comparisons=[];change({...create(),aging:s.aging,pairCost:s.pairCost},'Same request sequence restarted. You may now change the cost assumptions.');};for(const key of ['aging','pairCost'])app.querySelector(`#${key}`)?.addEventListener('change',e=>change(configure(s,{[key]:Number(e.target.value)}),'Cost assumption updated.'));app.querySelectorAll('[data-policy]').forEach(b=>b.onclick=()=>{const result=runPolicy(b.dataset.policy,{aging:s.aging,pairCost:s.pairCost});comparisons=comparisons.filter(c=>c.id!==b.dataset.policy);comparisons.push({id:b.dataset.policy,name:b.textContent,value:result.value});save();render();});app.querySelector('#export').onclick=()=>downloadText('exceptions-run.md',`# How exceptions accumulate\n\n${s.quarter}/6 quarters settled. Total value: ${f(s.value)} points. Ageing ${s.aging}; overlapping pair cost ${s.pairCost}.\n\n${s.history.map(h=>`- Q${h.quarter+1}: revenue ${f(h.revenue)}, setup ${f(h.changeCost)}, upkeep ${f(h.maintenance)}, retirement ${f(h.retirement)}, net ${f(h.net)}.`).join('\n')}\n\nFictional illustrative accounting; no empirical calibration.\n\n\`\`\`json\n${JSON.stringify(s,null,2)}\n\`\`\`\n`,'text/markdown');}
window.exceptionsExperiment={getState:()=>copy(s),move:(id,lane)=>change(move(s,id,lane),'Plan updated.'),advance:()=>change(advance(s),'Quarter settled.')};save();render();
